async function r(o){if(navigator.clipboard&&window.isSecureContext)try{return await navigator.clipboard.writeText(o),!0}catch(e){console.error("使用 navigator.clipboard 复制失败:",e)}try{const e=document.createElement("input");e.style.position="fixed",e.style.opacity="0",e.value=o,document.body.appendChild(e),e.select();const t=document.execCommand("copy");return document.body.removeChild(e),t?!0:(console.error("使用 execCommand 复制失败"),!1)}catch(e){return console.error("后备复制方法执行出错:",e),!1}}export{r as c};
